script.script:
import jenkins.model.Jenkins
import hudson.model.Result

def migrationBuildNumber = build.getEnvironment(listener).get("migration_build_number")
if (!(migrationBuildNumber ==~ /[1-9][0-9]*/)) {
    throw new Exception("A positive migration_build_number is required")
}
def migrationJob = Jenkins.instance.getItemByFullName("PIC-SURE Database Migrations")
def migrationRun = migrationJob?.getBuildByNumber(migrationBuildNumber.toInteger())
if (migrationRun == null || migrationRun.result != Result.SUCCESS) {
    throw new Exception("PIC-SURE Database Migrations build ${migrationBuildNumber} is not a completed successful build")
}
